import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Open Cube OS Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"root/ARCHITECTURE.md","filePath":"root/ARCHITECTURE.md"}'),t={name:"root/ARCHITECTURE.md"};function r(i,e,c,l,d,p){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="open-cube-os-architecture" tabindex="-1">Open Cube OS Architecture <a class="header-anchor" href="#open-cube-os-architecture" aria-label="Permalink to &quot;Open Cube OS Architecture&quot;">​</a></h1><p>This document describes L0 as it exists in the tree - every component named below is a real file you can open. Line counts and per-directory detail live in <code>docs/data/stats.json</code> (regenerate: <code>make api-docs</code>).</p><h2 id="the-big-picture" tabindex="-1">The big picture <a class="header-anchor" href="#the-big-picture" aria-label="Permalink to &quot;The big picture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                       GRUB 2.12 (hybrid BIOS + UEFI ISO)</span></span>
<span class="line"><span>                                     |  multiboot2 + kernel-as-module</span></span>
<span class="line"><span>        +----------------------------+----------------------------+</span></span>
<span class="line"><span>        |                 boot/boot.S                            |</span></span>
<span class="line"><span>        |   32-bit entry -&gt; GDT -&gt; 2 MiB identity map of the      |</span></span>
<span class="line"><span>        |   first 4 GiB -&gt; PAE+LME+PGE -&gt; long mode -&gt; kmain      |</span></span>
<span class="line"><span>        +----------------------------+----------------------------+</span></span>
<span class="line"><span>                                     |</span></span>
<span class="line"><span>   kernel/main.c  (kmain: bring-up order = the boot log you see)</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>   +----+------------+------------+-------------+------------+</span></span>
<span class="line"><span>   |                 |            |             |            |</span></span>
<span class="line"><span> kernel/arch/x86_64 kernel/core  kernel/mem   kernel/lib   kernel/crypto</span></span>
<span class="line"><span>   IDT/GDT/TSS      scheduler    PMM/VMM/heap string/tar  RSA/EC/AEAD/</span></span>
<span class="line"><span>   exceptions       syscalls 53   4 KiB pages  gzip/config  X.509/SHA</span></span>
<span class="line"><span>   IRQ 8259 remap   ring3+ELF    free-list     klog</span></span>
<span class="line"><span>   LAPIC/timers     signals      kmalloc</span></span>
<span class="line"><span>   context switch   soft timers</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>   +----------------+----------------+---------------+</span></span>
<span class="line"><span>   |                |                |               |</span></span>
<span class="line"><span> drivers/*        fs/              net/            shell/</span></span>
<span class="line"><span> 16 families      VFS + ramfs      e1000-family    parser/executor</span></span>
<span class="line"><span> block NVME AHCI  FAT32 exFAT      ARP IPv4 ICMP   233 commands</span></span>
<span class="line"><span> ATA DMA virtio   ext4             UDP DNS TCP     pipes/redirection</span></span>
<span class="line"><span> USB xHCI/EHCI/   node cache       sockets TLS     env/aliases</span></span>
<span class="line"><span> OHCI UHCI MSC    mount crossing   SSH client      line editor</span></span>
<span class="line"><span> HID audio serial congestion       sshd server    script lang</span></span>
<span class="line"><span> PCI PCIe ACPI    /etc volume      firewall        editor</span></span>
<span class="line"><span> I2C SMBus HPET                    tcp cc          TUI bridge</span></span>
<span class="line"><span> RTC TSC PM timer</span></span>
<span class="line"><span> wireless bt SD   tui/            chinese/        l1/</span></span>
<span class="line"><span> camera UVC IR    desktop,        CN console      162-numbered</span></span>
<span class="line"><span> gameport parallel menus, forms,  font 16x16      extension surface</span></span>
<span class="line"><span> SCSI LSI 53C8xx  editor, apps    pinyin IME      + solib loader</span></span></code></pre></div><h2 id="boot-flow-what-the-serial-log-shows-in-order" tabindex="-1">Boot flow (what the serial log shows, in order) <a class="header-anchor" href="#boot-flow-what-the-serial-log-shows-in-order" aria-label="Permalink to &quot;Boot flow (what the serial log shows, in order)&quot;">​</a></h2><ol><li>GRUB loads <code>boot/opencube.elf</code> (the kernel is also attached as a multiboot2 module tagged <code>self</code> - the installer pattern, so <code>install</code>/<code>abdisk</code> can copy the <em>exact</em> running kernel onto a disk).</li><li><code>boot/boot.S</code>: 32-bit entry point, own GDT, identity-map the first 4 GiB with 2 MiB pages, PAE + LME + PGE, switch to 64-bit long mode, call <code>kmain</code>.</li><li><code>kernel/arch/x86_64/arch_multiboot2.c</code> parses the multiboot2 info (framebuffer, memory map, command line, ACPI RSDP tags) - with full malformed-input hardening: per-tag minimums, NUL-termination checks, truncated-tag rejection.</li><li><code>kmain</code> brings up, in boot-log order: framebuffer console and font, IDT/GDT/TSS (256 gates, IST stacks for #DF/#MC and debug), 8259 PIC remap, PIT @ 100 Hz, PS/2 keyboard, COM1 serial RX, line editor, exceptions (with a live #DE/#UD/#PF self-test), PMM, VMM, heap, then the driver domains, VFS, network, shell.</li><li>Shell registers its 233 commands (<code>shell command system (233 commands)</code> line), crash recovery arms, and the <code>oc&gt;</code> prompt appears.</li></ol><h2 id="memory-management" tabindex="-1">Memory management <a class="header-anchor" href="#memory-management" aria-label="Permalink to &quot;Memory management&quot;">​</a></h2><ul><li><strong>PMM</strong> (<code>kernel/mem/mem_pmm.{c,h}</code>): bitmap allocator over 4 KiB page frames from the multiboot2 memory map; reserved regions (kernel code, framebuffer, mbi) marked used at init; O(1) alloc/free.</li><li><strong>VMM</strong> (<code>kernel/mem/mem_vmm.{c,h}</code>): 4-level page tables; the kernel keeps the boot-time identity map of the first 4 GiB; APIs create and manipulate additional address spaces (user processes). Page protection flags map to rw/nx/user bits.</li><li><strong>Heap</strong> (<code>kernel/mem/mem_heap.{c,h}</code>): kmalloc/kfree/krealloc/ kzalloc, free-list with first-fit and coalescing, 16-byte aligned blocks (a historical 40-vs-32-byte header bug taught us the hard way), 16 MiB fail-fast ceiling.</li><li><strong>#PF growth</strong>: stack-growth and heap-growth page faults are real fault handling in <code>kmain</code>&#39;s exception path - illegal accesses escalate to the crash path.</li></ul><h2 id="scheduling-and-time" tabindex="-1">Scheduling and time <a class="header-anchor" href="#scheduling-and-time" aria-label="Permalink to &quot;Scheduling and time&quot;">​</a></h2><ul><li><strong>Scheduler</strong> (<code>kernel/core/core_sched.{c,h}</code>): preemptive, priority + time-slice round-robin over task control blocks; context switch in <code>arch/x86_64/arch_context_switch.S</code>-family assembly with ABI-probe-verified alignment.</li><li><strong>Timer</strong> (<code>kernel/core/core_timer.{c,h}</code>): PIT at 100 Hz drives ticks, <code>g_boot_time_ms</code> and the soft-timer wheel. HPET, the ACPI PM timer and the TSC are supported as <em>additional</em> time sources (<code>drivers/time/</code>).</li><li><strong>Watchdog</strong> (<code>kernel/core/core_watchdog.{c,h}</code>): monitored task slots with timeout policy (the <code>watchdog</code> command), plus true hardware watchdog bring-up where firmware offers it - Intel TCO (verified live on QEMU q35: PMBASE discovery, armed status, real hard reset + second boot) and ACPI WDAT tables.</li></ul><h2 id="interrupts-and-exceptions" tabindex="-1">Interrupts and exceptions <a class="header-anchor" href="#interrupts-and-exceptions" aria-label="Permalink to &quot;Interrupts and exceptions&quot;">​</a></h2><p><code>kernel/arch/x86_64/arch_idt.{c,h}</code> + <code>arch_irq.c</code>: 256-entry IDT, TSS with IST1 (panic stack for #DF/#MC) and IST2 (dedicated exception-exit stack - never a context switch on IST2), 8259 remap to vectors 32-47, LAPIC handling, and a full exception frame path that feeds crash dump generation. A live 3/3 (#DE/#UD/#PF) self-test runs on every boot.</p><h2 id="ring-3-syscalls-processes" tabindex="-1">Ring 3, syscalls, processes <a class="header-anchor" href="#ring-3-syscalls-processes" aria-label="Permalink to &quot;Ring 3, syscalls, processes&quot;">​</a></h2><ul><li><strong>Syscall ABI</strong> (<code>kernel/core/core_syscall.h</code>): <code>rax</code>=number, <code>rdi/rsi/rdx/r10</code>=args, <code>rax</code>=result. 53 syscall numbers (verify: <code>grep -c &#39;#define SYS_&#39; kernel/core/core_syscall.h</code>).</li><li><strong>User mode</strong> (<code>kernel/core/core_usermode.{c,h}</code>): ELF loader, process table, signals, ring-3 entry/fork in assembly.</li><li><strong>User programs</strong> (<code>userprogs/</code>): hello, fork/exec/pipe/signal/ select/mmap tests, dynamic linking with a real in-tree loader (<code>libs/ld_so.c</code>) - shared objects, <code>dlsym</code>, PIE and relocation tests all run as shell commands.</li></ul><h2 id="filesystems" tabindex="-1">Filesystems <a class="header-anchor" href="#filesystems" aria-label="Permalink to &quot;Filesystems&quot;">​</a></h2><ul><li><strong>VFS</strong> (<code>fs/fs_vfs.{c,h}</code>): uniform open/read/write/seek/close/ stat/mkdir/rmdir/readdir/lookup over registered fs types; the node tree crosses mount points transparently; per-fs case sensitivity; permission bits enforced; i64 seek.</li><li><strong>Filesystems</strong>: FAT32 (LFN with alias + collision scan + checksum validation, dual-FAT mirror, FSINFO), exFAT (active FAT), ext4 (read/write with extent support), ramfs (sparse holes zeroed).</li><li><strong>Block layer</strong> (<code>drivers/block/driver_block_blk.{c,h}</code>): register/ read/write/flush with per-instance names, partition scanning, AHCI, ATA/ATA-DMA (with PRDT alignment guaranteed by the 32-byte heap header), NVMe, virtio-blk.</li><li><strong>/etc volume</strong>: a 32 MiB FAT32 image mounted at /etc holding <code>opencube.conf</code>, SSH host keys, kernel logs - so configuration survives reboots (<code>etc.img</code> target).</li></ul><h2 id="network-stack" tabindex="-1">Network stack <a class="header-anchor" href="#network-stack" aria-label="Permalink to &quot;Network stack&quot;">​</a></h2><p><code>net/net_core.{c,h}</code> and friends - a self-contained stack: PCI discovery, e1000-family NIC drivers (e1000/e1000e/igb/ixgbe; rtl8139/ rtl8169-family; BCM57xx), Ethernet + ARP + IPv4 + ICMP + UDP + DNS + TCP with congestion control (<code>net_tcp_cc.c</code>), a socket API for user programs, stateful firewall, <code>wget</code>/<code>dns</code>/<code>ping</code>/<code>route</code> commands. On top of it: a TLS 1.2/1.3 client with RSA/ECDHE, X.509 chain verification (RFC 6125 hostname policy) and a real SSH client + SSH server (<code>net_sshd.c</code>, key exchange via curve25519/ed-style primitives, host keys on /etc). The DRBG seeding is RDRAND + re-mixed RDTSC (NIST SP 800-90A HMAC_DRBG).</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h2><p>16 families under <code>drivers/</code> - each with its own bring-up manual page under <code>docs/drivers/</code>. Highlights: UHCI/OHCI/EHCI/xHCI USB stacks with MSC (mass storage), HID, serial, audio classes; HDA/AC97/SB16/ ES1370/virtio sound; i2c + SMBus; wireless (ath/brcm/iwlwifi/rtlwifi families) and bluetooth (HCI/L2CAP/RFCOMM/SDP/SPP + HID) layers; UVC cameras with MJPEG; SD/SDHCI; SCSI (LSI 53C8xx family); ACPI with a real AML namespace walker (FADT/DSDT/MCFG, S3 suspend/resume in <code>arch_acpi_s3*.S</code>); chipset time sources (HPET/PM timer/TSC/CMOS RTC).</p><h2 id="shell-and-tui" tabindex="-1">Shell and TUI <a class="header-anchor" href="#shell-and-tui" aria-label="Permalink to &quot;Shell and TUI&quot;">​</a></h2><ul><li><strong>Shell</strong> (<code>shell/</code>): tokeniser, env vars, aliases, pipes, redirection, background jobs, wildcards, command chains (<code>;</code> <code>&amp;&amp;</code> <code>||</code>), cwd, script language, <code>help -a/-w</code> two views, 233 commands, line editor with history, a text <code>editor</code>.</li><li><strong>TUI</strong> (<code>tui/</code>): the windowing layer on top of the framebuffer - desktop with taskbar/launcher, menus, forms, panels, text widgets, a TUI editor, system monitor apps, and the extension surface <code>tui/tui_ext.h</code> (37 callable declarations) that L1 modules use.</li></ul><h2 id="chinese-console-layer" tabindex="-1">Chinese console layer <a class="header-anchor" href="#chinese-console-layer" aria-label="Permalink to &quot;Chinese console layer&quot;">​</a></h2><p><code>chinese/</code> adds a 16x16 bitmap font, GB-encoded console rendering, pinyin IME, and CN variants of the TUI hardware/net/sysinfo apps - selectable at build time (<code>CONFIG_CHINESE</code>), ASCII-equivalent fallbacks when disabled. System strings remain ASCII by contract.</p><h2 id="l1-extension-surface" tabindex="-1">L1 extension surface <a class="header-anchor" href="#l1-extension-surface" aria-label="Permalink to &quot;L1 extension surface&quot;">​</a></h2><p>The numbered 162-interface surface (see <code>INTERFACES.md</code>) plus the driver/OTA/watchdog/health/klog headers; a shared-object loader (<code>libs/ld_so.c</code>) lets L1 modules load at runtime. The TUI command bridge demonstrates the pattern end-to-end.</p><h2 id="ota-and-a-b-updates" tabindex="-1">OTA and A/B updates <a class="header-anchor" href="#ota-and-a-b-updates" aria-label="Permalink to &quot;OTA and A/B updates&quot;">​</a></h2><p><code>kernel/ota/</code>: update manifest verification (SHA256 + signature), download, staged install onto A/B slots (<code>ota_ab.{c,h}</code>), rollback, boot-slot flags consumed by the GRUB menu (slot ISO / A / B). The <code>update</code> command chain runs the whole flow; <code>ab_partition_test</code> exercises slot management on a scratch disk.</p><h2 id="crash-recovery" tabindex="-1">Crash recovery <a class="header-anchor" href="#crash-recovery" aria-label="Permalink to &quot;Crash recovery&quot;">​</a></h2><p><code>kernel/core/core_crash.c</code> + <code>shell/shell_cmds_crash.c</code>: panic path with register dump to serial + crashlog on the /etc volume, dump inspection via <code>dumpinfo</code>, an in-guest <code>crashtest</code>, and the WinRE-style recovery posture: the system boots into the <code>oc&gt;</code> shell by default, so &quot;recovery&quot; is the primary interface, not a special mode.</p>`,30)])])}const u=a(t,[["render",r]]);export{m as __pageData,u as default};
